\[
\begin{aligned}
\frac{D}{Dt}
&=\frac{\partial}{\partial t}+(\vec{v}\cdot\nabla)\\[6pt]
&=\frac{\partial}{\partial t}+\left(\sum_{i=0}^{3}\vec{\delta}_{i}v_i\cdot\sum_{j=0}^{3}\vec{\delta}_{j}\frac{\partial}{\partial x_j}\right)\\[6pt]
&=\frac{\partial}{\partial t}+\left(\sum_{i=0}^{3}\sum_{j=0}^{3}\vec{\delta}_{i}v_i\cdot\vec{\delta}_{j}\frac{\partial}{\partial x_j}\right)\\[6pt]
&=\frac{\partial}{\partial t}+\sum_{i=0}^{3}\sum_{j=0}^{3}(\vec{\delta}_{i}\cdot\vec{\delta}_{j})v_i\frac{\partial}{\partial x_j}\\[6pt]
&=\frac{\partial}{\partial t}+\sum_{i=0}^{3}\sum_{j=0}^{3}\delta_{ij}v_i\frac{\partial}{\partial x_j}\\[6pt]
&=\frac{\partial}{\partial t}+\sum_{i=0}^{3}v_i\frac{\partial}{\partial x_i}\\[6pt]
&=\frac{\partial}{\partial t}+v_x\frac{\partial}{\partial x_x}+v_y\frac{\partial}{\partial x_y}+v_z\frac{\partial}{\partial x_z}
\end{aligned}
